'use strict';
const historyState={ready:false,error:'',snapshots:[],snapshotChanges:[],reviews:[],legacy:{runs:[],changes:[]},dependencies:[],basis:'features',series:'total',week:'',changeField:'',kind:'',risk:'',compare:[],viewedId:'',loaded:false};
const seriesColors=['#087e78','#3867ac','#a5538a','#b87716','#7863b1'];
async function api(path,body){const res=await fetch('/api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const value=await res.json();if(!res.ok)throw new Error(value.error||'Request failed.');return value;}
async function loadHistory(){try{const h=await api('history');Object.assign(historyState,{...h,ready:true,error:''});}catch(e){historyState.ready=false;historyState.error=e.message;historyState.snapshots=[HistoryCore.summarize(published,'published')];}return historyState;}
let reportStyles='';
async function initIntelligence(){Promise.all(['style.css','intelligence.css'].map(u=>fetch(u).then(r=>r.text()))).then(css=>reportStyles=css.join('\n')).catch(()=>{});const results=await Promise.allSettled([fetch('legacy-history.json').then(r=>{if(!r.ok)throw Error('Date history unavailable');return r.json()}),fetch('dependencies.json').then(r=>{if(!r.ok)throw Error('Dependency evidence unavailable');return r.json()})]);if(results[0].status==='fulfilled')historyState.legacy=results[0].value;else historyState.error=results[0].reason.message;if(results[1].status==='fulfilled')historyState.dependencies=results[1].value.dependencies;else historyState.error+=' '+results[1].reason.message;const evidenceError=historyState.error;await loadHistory();if(evidenceError)historyState.error+=' '+evidenceError;historyState.loaded=true;if(historyState.ready&&historyState.snapshots.length&&data===published){const latest=historyState.snapshots.at(-1);try{data=await api('snapshots/'+encodeURIComponent(latest.id));historyState.viewedId=latest.id;data.mode='saved';}catch(e){historyState.error=e.message;}}controls();updateSource();render();}
const allDateChanges=()=>[...historyState.legacy.changes,...historyState.snapshotChanges].sort((a,b)=>a.observedAt.localeCompare(b.observedAt));
const currentDeps=()=>historyState.dependencies.map(d=>HistoryCore.dependency(d,data.rows));
const relevantDeps=rows=>{const keys=new Set(rows.map(r=>r.key));return currentDeps().filter(d=>keys.has(d.predecessorKey)||keys.has(d.successorKey));};
function currentChanges(rows){const legacy=HistoryCore.changesFor(allDateChanges(),rows);return legacy.filter(c=>(!historyState.week||HistoryCore.week(c.observedAt)===historyState.week)&&(!historyState.changeField||c.field===historyState.changeField)&&(!historyState.kind||c.kind===historyState.kind));}
function currentWarnings(rows){return HistoryCore.warnings(rows,HistoryCore.changesFor(allDateChanges(),rows),relevantDeps(rows),historyState.reviews,state.asOf);}
function intelligenceBanner(){return `<div class="intel-banner"><div><span class="eyebrow">PROGRAM CONTROL BOARD</span><h3>Progress. Movement. Decisions.</h3><p>Evidence captured on request · targets and actual completion remain separate.</p></div><div class="intel-links">${[['history','Weekly evolution'],['dates','Date movement'],['risks','Early warnings'],['dependencies','Dependencies'],['report','Management report']].map(([v,t])=>`<button data-view="${v}">${t} →</button>`).join('')}</div></div>`;}
function observations(){return HistoryCore.weekly(historyState.basis==='features'?historyState.snapshots:HistoryCore.legacyObservations(historyState.legacy.runs,data.rows));}
function trendChart(points){const series=[['total',historyState.basis==='features'?'Total focus features':'Total mapped focus tickets'],...HistoryCore.focus.map(s=>[s,s])].filter(([k])=>historyState.series==='total'||k===historyState.series);const value=(o,k)=>!o?null:k==='total'?o.focusRows:o.groups[k]?.rows||0;const W=1000,H=280,L=54,R=22,T=20,B=45,max=Math.max(1,...points.flatMap(p=>series.map(([k])=>value(p.observation,k)||0))),x=i=>L+(points.length<2?(W-L-R)/2:i*(W-L-R)/(points.length-1)),y=v=>H-B-v/max*(H-T-B);let content='';for(let j=0;j<=4;j++){const v=Math.round(max*j/4);content+=`<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" stroke="#dce5ee"/><text x="${L-10}" y="${y(v)+5}" text-anchor="end">${v}</text>`;}
 for(const [key,label] of series){const color=seriesColors[key==='total'?0:HistoryCore.focus.indexOf(key)+1];let previous=null;points.forEach((p,i)=>{const v=value(p.observation,key);if(v===null){previous=null;return;}if(previous)content+=`<line x1="${previous.x}" y1="${previous.y}" x2="${x(i)}" y2="${y(v)}" stroke="${color}" stroke-width="3"/>`;content+=`<a href="#weekly-data" data-week="${p.week}" aria-label="Week ${p.week}, ${esc(label)}, ${v}"><circle cx="${x(i)}" cy="${y(v)}" r="5" fill="${color}"><title>${esc(label)} · ${p.week}: ${v}</title></circle></a>`;previous={x:x(i),y:y(v)};});}
 points.forEach((p,i)=>{if(points.length<14||i%Math.ceil(points.length/12)===0||i===points.length-1)content+=`<text x="${x(i)}" y="${H-15}" text-anchor="middle">${p.week.slice(5)}</text>`;});return `<div class="trend-scroll"><svg class="trend-chart" viewBox="0 0 ${W} ${H}" role="group" aria-label="Weekly ${historyState.basis==='features'?'feature row':'historical ticket'} observations; accessible values follow in the table">${content}</svg></div><div class="chart-key">${series.map(([k,t])=>`<span><i style="background:${seriesColors[k==='total'?0:HistoryCore.focus.indexOf(k)+1]}"></i>${esc(k==='total'?'Focus total':t)}</span>`).join('')}</div>`;
}
function renderHistory(){const points=observations();return `<div class="intel-page"><div class="section-intro"><div><span class="eyebrow">WEEK OVER WEEK</span><h3>Scope evolution</h3><p>Last observed snapshot in each Monday–Sunday week, Korea time. No interpolation across missing weeks.</p></div><label>Evidence<select id="history-basis"><option value="features" ${historyState.basis==='features'?'selected':''}>Complete feature rows</option><option value="tickets" ${historyState.basis==='tickets'?'selected':''}>Historical Jira ticket observations</option></select></label></div><p class="evidence-note">${historyState.basis==='features'?'Feature counts include unticketed rows. Full worksheet observations begin on 16 Sep 2026; earlier full-feature totals are unavailable. Multiple captures in one week produce one weekly point.':'Historical database observations from July–September 2026 count unique Jira tickets only. Focus areas are mapped using the currently displayed workbook, because historical Level 1 labels were not stored. This is not a reconstruction of past feature totals.'}</p><div class="inline-controls"><label>Show<select id="history-series"><option value="total">Focus total + all four areas</option>${HistoryCore.focus.map(s=>`<option ${historyState.series===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><button data-view="dates">Inspect date changes →</button></div><article class="chart-card">${points.length?trendChart(points):'<p>No observations available.</p>'}${points.filter(p=>p.observation).length===1?'<p class="evidence-note">One observed week is available. A trend will form when you request refreshes in later weeks.</p>':''}<details id="weekly-data" open><summary>Weekly values and observation dates</summary><div class="table-scroll"><table><thead><tr><th>Week starting</th><th>Observed</th><th>Focus total</th>${HistoryCore.focus.map(s=>`<th>${esc(s)}</th>`).join('')}</tr></thead><tbody>${points.map(p=>`<tr><th scope="row">${p.week}</th><td>${p.observation?fmt(p.observation.observedAt.slice(0,10)):'No observation'}</td>${['total',...HistoryCore.focus].map(k=>`<td>${p.observation?(k==='total'?p.observation.focusRows:p.observation.groups[k]?.rows||0):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></article>${weeklyStatusChart()}<article class="chart-card snapshot-card"><h3>Durable snapshot archive</h3><p>Refresh only on request. Load a workbook to capture a new observation and retain the complete original .xlsx file. The older baseline contains the parsed first worksheet only.</p><p class="storage-state ${historyState.ready?'':'storage-error'}">${historyState.ready?'Persistent storage connected · '+historyState.snapshots.length+' observations retained':esc(historyState.error||'Connecting to history…')}</p><button id="save-snapshot">Record current workbook now</button><button id="retry-history">Reload saved history</button><div class="table-scroll"><table><thead><tr><th>Observed (KST)</th><th>Workbook saved</th><th>All plan rows</th><th>Focus rows</th><th>Actions</th></tr></thead><tbody>${[...historyState.snapshots].reverse().map(s=>`<tr><td>${esc(new Date(s.observedAt).toLocaleString('en-GB',{timeZone:'Asia/Seoul'}))}${historyState.viewedId===s.id?' · Viewing':''}</td><td>${esc(fmt(s.sourceModifiedAt?.slice(0,10)))}</td><td>${s.rowCount}</td><td>${s.focusRows}</td><td><button data-load-snapshot="${esc(s.id)}">View</button> <button data-download-snapshot="${esc(s.id)}">${s.hasWorkbook?'Download .xlsx':'Download parsed data'}</button></td></tr>`).join('')}</tbody></table></div><h3>Compare complete snapshots</h3><div class="inline-controls"><label>From<select id="compare-from">${snapshotOptions(false)}</select></label><label>To<select id="compare-to">${snapshotOptions(true)}</select></label><button id="compare-snapshots">Compare</button></div><div id="snapshot-diff">${renderDiff()}</div></article></div>`;}
function snapshotOptions(last){return historyState.snapshots.map((s,i)=>`<option value="${esc(s.id)}" ${last&&i===historyState.snapshots.length-1?'selected':''}>${esc(new Date(s.observedAt).toLocaleString('en-GB',{timeZone:'Asia/Seoul'}))} · ${s.rowCount} rows</option>`).join('')}
function weeklyStatusChart(){const points=HistoryCore.weekly(historyState.snapshots),group=historyState.series==='total'?HistoryCore.focus:[historyState.series];const values=points.map(p=>({week:p.week,counts:p.observation?Object.fromEntries(Analytics.statuses.map(k=>[k,group.reduce((n,s)=>n+(p.observation.groups[s]?.statuses?.[k]||0),0)])):null}));const max=Math.max(1,...values.map(p=>p.counts?Object.values(p.counts).reduce((a,b)=>a+b,0):0));return `<article class="chart-card"><h3>Weekly status evolution</h3><p>Complete workbook snapshots only · ${esc(historyState.series==='total'?'all four focus areas':historyState.series)} · P-D and B0 Done remain separate.</p><div class="weekly-status-bars">${values.map(p=>`<div class="weekly-status-row"><span>${p.week}</span>${p.counts?`<div class="weekly-status-track">${Object.entries(p.counts).filter(([,n])=>n).map(([k,n])=>`<span style="width:${n/max*100}%;background:${colors[k]}" title="${esc(Plan.labels[k])}: ${n}"><span class="sr-only">${esc(Plan.labels[k])}: </span>${n}</span>`).join('')}</div>`:'<span>No observation</span>'}</div>`).join('')}</div>${smallLegend()}<details><summary>Status values</summary><div class="table-scroll"><table><thead><tr><th>Week</th>${Analytics.statuses.map(s=>`<th>${esc(Plan.labels[s])}</th>`).join('')}</tr></thead><tbody>${values.map(p=>`<tr><th>${p.week}</th>${Analytics.statuses.map(s=>`<td>${p.counts?p.counts[s]:'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></article>`;}
function renderDiff(){return historyState.compare.length?`<div class="table-scroll"><table><thead><tr><th>Feature</th><th>Changed field</th><th>Before → after</th></tr></thead><tbody>${historyState.compare.map(d=>`<tr><td>${esc(d.key)} ${esc(d.title)}</td><td>${esc(d.kind)}</td><td>${esc(d.detail)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Choose two snapshots to inspect added, removed and changed rows. Duplicate ticket keys are flagged for manual pairing.</p>';}
function renderDates(rows){const changes=currentChanges(rows),all=HistoryCore.changesFor(allDateChanges(),rows),weeks=[...new Set(all.map(c=>HistoryCore.week(c.observedAt)))].sort().reverse(),slipped=changes.filter(c=>c.kind==='slipped'),pulled=changes.filter(c=>c.kind==='pulled-in');return `<div class="intel-page"><div class="section-intro"><div><span class="eyebrow">DELIVERY MOVEMENT</span><h3>Targets, changes and milestone gaps</h3><p>Feature Done target = workbook “Feature Due Date” (column L). Actual completion dates are not recorded in this source.</p></div></div><div class="signal-grid"><div><strong>${changes.length}</strong><span>Observed date changes</span></div><div><strong>${slipped.length}</strong><span>Moved later</span></div><div><strong>${pulled.length}</strong><span>Moved earlier</span></div><div><strong>${changes.filter(c=>['assigned','cleared'].includes(c.kind)).length}</strong><span>Assigned / cleared</span></div></div><article class="chart-card"><h3>P-D → Feature Done targets</h3><p>Status records milestone completion, without an actual completion date. A negative gap needs scope review.</p><div class="table-scroll"><table><thead><tr><th>Feature</th><th>P-D target</th><th>Feature Done target</th><th>Gap</th><th>Recorded completion</th></tr></thead><tbody>${rows.map(r=>{const gap=HistoryCore.days(r.due,r.preDue);return `<tr><td><button class="text-button" data-row="${r.row}">${esc(r.key||r.title)}</button><span class="subline">${esc(r.title)}</span></td><td>${esc(fmt(r.preDue))}</td><td>${esc(fmt(r.due))}</td><td class="${gap<0?'risk-text':''}">${gap===null?'Unavailable':gap+' days'}</td><td>${r.status==='Done'?'B0 done; actual date unavailable':r.status==='P-D'?'P-D done; B0 unconfirmed':'No completion recorded'}</td></tr>`}).join('')}</tbody></table></div></article><article class="chart-card"><h3>Date change ledger</h3><p>Read-only extraction of 26 saved database runs, plus changes between newly saved workbook snapshots. Each change compares consecutive observed values for the same uniquely identified Jira ticket. It is not the exact time the Jira edit occurred.</p><div class="inline-controls"><label>Week<select id="change-week"><option value="">All observed weeks</option>${weeks.map(w=>`<option ${historyState.week===w?'selected':''}>${w}</option>`).join('')}</select></label><label>Milestone<select id="change-field"><option value="">Both targets</option><option value="preDue" ${historyState.changeField==='preDue'?'selected':''}>P-D</option><option value="due" ${historyState.changeField==='due'?'selected':''}>Feature Done</option></select></label><label>Movement<select id="change-kind"><option value="">All changes</option>${['slipped','pulled-in','assigned','cleared','changed'].map(k=>`<option ${historyState.kind===k?'selected':''}>${k}</option>`).join('')}</select></label></div><div class="table-scroll ledger"><table><thead><tr><th>Observed / source</th><th>Ticket</th><th>Milestone</th><th>Previous target</th><th>New target</th><th>Movement</th></tr></thead><tbody>${[...changes].reverse().map(c=>`<tr><td>${esc(c.observedAt.slice(0,10))}<span class="subline">${esc(c.source||"Jira date database")}</span></td><td>${esc(c.key)}</td><td>${c.field==='preDue'?'P-D':'Feature Done'}</td><td>${esc(fmt(c.old))}</td><td>${esc(fmt(c.new))}</td><td class="${c.kind==='slipped'?'risk-text':''}">${esc(c.kind)}${c.days!==null?' · '+(c.days>0?'+':'')+c.days+'d':''}</td></tr>`).join('')||'<tr><td colspan="6">No observed date changes match these filters.</td></tr>'}</tbody></table></div><p class="chart-footnote">Source: duedates.db, extracted ${esc(historyState.legacy.extractedAt||'unavailable')}. Current section membership is used when filtering. New workbook comparisons are available in Weekly evolution.</p></article></div>`;}
function renderRisks(rows){const all=currentWarnings(rows),kinds=[...new Set(all.map(a=>a.kind))],items=all.filter(a=>!historyState.risk||a.kind===historyState.risk);return `<div class="intel-page"><div class="section-intro"><div><span class="eyebrow">EARLY WARNING</span><h3>${all.length} signals across ${new Set(all.map(a=>a.row)).size} rows</h3><p>Review signals, not confirmed blockers. ${esc(state.asOf)} is the comparison date; source status may be older.</p></div><label>As of<input type="date" id="as-of" value="${state.asOf}"></label></div><div class="risk-chips"><button data-risk="" aria-pressed="${!historyState.risk}">All ${all.length}</button>${kinds.map(k=>`<button data-risk="${esc(k)}" aria-pressed="${historyState.risk===k}">${esc(k)} <b>${all.filter(a=>a.kind===k).length}</b></button>`).join('')}</div><div class="warning-list">${items.map(a=>`<article class="warning ${a.severity}"><div><span class="risk-type">${esc(a.kind)}</span><h4><button data-row="${a.row}">${esc(a.key||'Row '+a.row)} · ${esc(a.title)}</button></h4><p>${esc(a.detail)}</p><small>Review owner: ${esc(a.owner)||'Unassigned — assign an owner'}</small></div>${a.dependencyId?`<button data-dependency="${esc(a.dependencyId)}">Review hypothesis →</button>`:''}</article>`).join('')||'<p>No matching signals. This does not establish that the plan has no risks.</p>'}</div><p class="evidence-note">No workload, effort, actual finish dates or live Jira dependencies are available. These rules identify data and schedule signals for human review; they cannot guarantee detection of all project issues.</p></div>`;}
const riskLabels={conditional:'Conditional final-date risk',overlap:'Phase overlap — validate baseline',aligned:'No final-date inversion',missing:'Dates incomplete',unresolved:'Ticket missing or ambiguous',completed:'Predecessor recorded Done'};
function renderDependencies(rows){const deps=relevantDeps(rows);return `<div class="intel-page"><div class="section-intro"><div><span class="eyebrow">LOGICALLY INFERRED · UNCONFIRMED</span><h3>Dependency review board</h3><p>${deps.length} hypotheses touch the current selection. Every relationship needs owner review; no Jira links have been created.</p></div></div><p class="evidence-note">Confidence describes the semantic relationship, not verified scheduling precedence. A predecessor final target after a successor P-D target can be compatible with partial delivery. Final-to-final inversions are conditional risks, not proven blockers.</p><div class="dependency-grid">${deps.map(d=>{const rev=historyState.reviews.find(r=>r.id===d.id);return `<button class="dependency-card ${d.risk}" data-dependency="${esc(d.id)}"><span class="dep-top">${esc(d.confidence)} confidence <span>${esc(rev?.decision||'Awaiting owner review')}</span></span><span class="dep-flow"><span><b>${esc(d.predecessorKey)}</b><small>${esc(d.predecessorTitle)}</small><em>${esc(d.a?.owner||'Owner missing')}</em></span><i aria-label="potentially enables">→</i><span><b>${esc(d.successorKey)}</b><small>${esc(d.successorTitle)}</small><em>${esc(d.b?.owner||'Owner missing')}</em></span></span><span class="dep-risk">${riskLabels[d.risk]}${d.risk==='conditional'?' · +'+d.lag+' days':''}</span></button>`}).join('')||'<p>No hypotheses touch these rows. This does not mean no dependencies exist.</p>'}</div></div>`;}
function showDependency(id){const d=currentDeps().find(x=>x.id===id);if(!d)return;const rev=historyState.reviews.find(r=>r.id===id);$('detail-eyebrow').textContent='INFERRED DEPENDENCY · NOT RECORDED IN JIRA';$('detail-body').innerHTML=`<h2>${esc(d.predecessorKey)} → ${esc(d.successorKey)}</h2><p><b>${esc(d.predecessorTitle)}</b> may enable <b>${esc(d.successorTitle)}</b>.</p><p>${esc(d.rationale)}</p><dl class="detail-grid"><div><dt>Confidence</dt><dd>${esc(d.confidence)} — semantic inference only</dd></div><div><dt>Current date assessment</dt><dd>${riskLabels[d.risk]}${d.lag!==null?' · final target gap '+d.lag+'d':''}</dd></div><div><dt>Upstream owner / final target</dt><dd>${esc(d.a?.owner||'Unknown')} · ${esc(fmt(d.a?.due))}</dd></div><div><dt>Downstream owner / P-D / final target</dt><dd>${esc(d.b?.owner||'Unknown')} · ${esc(fmt(d.b?.preDue))} / ${esc(fmt(d.b?.due))}</dd></div></dl><h3>Evidence and assumptions</h3><p>Source rows at inference: ${d.evidenceSourceRows.map(esc).join(', ')}. Date checks use the currently viewed workbook.</p><ul>${d.caveats.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>Owner review record</h3><p>Record the reviewer, decision and evidence. Acceptance here does not create a Jira dependency or establish a confirmed blocker.</p><form id="dependency-review-form" data-id="${esc(d.id)}"><label>Decision<select name="decision">${[['unreviewed','Awaiting owner review'],['accepted','Accepted for planning'],['rejected','Rejected hypothesis']].map(([v,t])=>`<option value="${v}" ${rev?.decision===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Reviewer and evidence / required handoff<textarea name="note" maxlength="2000" rows="4" placeholder="Reviewer name; required artifact or baseline; release scope; decision evidence">${esc(rev?.note||'')}</textarea></label><button class="primary">Save review</button><p id="review-result" role="status">${rev?'Saved '+esc(rev.updated_at):'No owner review recorded.'}</p></form>`;$('detail').showModal();}
function reportMarkup(rows){const warnings=currentWarnings(rows),changes=HistoryCore.changesFor(allDateChanges(),rows),late=warnings.filter(w=>w.kind==='Past Feature Done target'),deps=relevantDeps(rows).filter(d=>d.risk==='conditional'&&historyState.reviews.find(r=>r.id===d.id)?.decision!=='rejected'),counts=Analytics.countStatus(rows);return `<article class="management-report"><div class="report-brand">BOS SEMICONDUCTOR <span>EAGLE-N B0</span></div><h2>Software delivery review</h2><p>${esc(Analytics.scopes[state.mode].title)} · ${esc(state.asOf)} · ${rows.length} selected plan rows</p><div class="signal-grid"><div><strong>${counts.Done}</strong><span>B0 done / ${rows.length}</span></div><div><strong>${counts['P-D']}</strong><span>P-D done, B0 pending</span></div><div><strong>${late.length}</strong><span>Past final target</span></div><div><strong>${deps.length}</strong><span>Conditional dependencies</span></div></div><h3>Management attention</h3><p>${counts.D+counts.R} rows carry a recorded delay or risk; ${counts.Unknown} have no recorded status. ${changes.filter(c=>c.kind==='slipped').length} target postponements were observed in the captured history for tickets in this selection. These events are not unique features.</p><h3>Decisions and owner follow-up</h3><ol>${warnings.filter(a=>a.severity!=='review').slice(0,12).map(a=>`<li><b>${esc(a.key||a.title)}</b> — ${esc(a.detail)} <span>Owner: ${esc(a.owner)||'Assign owner'}.</span></li>`).join('')||'<li>No high-priority signals identified in the available records.</li>'}</ol><h3>Focus-area status</h3><div class="table-scroll"><table><thead><tr><th>Area</th><th>Rows</th><th>B0 done</th><th>P-D done</th><th>Delayed / risky</th><th>Status unknown</th></tr></thead><tbody>${Analytics.groupRows(rows,'section').map(g=>`<tr><th>${esc(g.label)}</th><td>${g.total}</td><td>${g.statuses.Done}</td><td>${g.statuses['P-D']}</td><td>${g.statuses.D+g.statuses.R}</td><td>${g.statuses.Unknown}</td></tr>`).join('')}</tbody></table></div><h3>Evidence and limits</h3><p>Workbook: ${esc(data.name)}; saved ${esc(data.modifiedAt)}. Worksheet: ${esc(data.sheet)}. Full-feature weekly observations start on 16 September 2026. Historical ticket date observations: 21 July–15 September 2026. All dates are targets; actual completion dates are unavailable. Dependency hypotheses remain unconfirmed in Jira. Refresh cadence: only on request.</p><p>${esc(historyState.error)||'Persistent snapshot archive is connected.'}</p></article>`;}
function renderReport(rows){return `<div class="intel-page"><div class="inline-controls no-print"><button id="print-report" class="primary">Print / save PDF</button><button id="download-report">Download management report</button><span>Uses the current scope and filters</span></div>${reportMarkup(rows)}</div>`;}
function renderIntelligence(rows){const views={history:()=>renderHistory(),dates:()=>renderDates(rows),risks:()=>renderRisks(rows),dependencies:()=>renderDependencies(rows),report:()=>renderReport(rows)};return (historyState.error?`<p class="storage-error">${esc(historyState.error)}</p>`:'')+views[state.view]();}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function saveCurrent(){if(!data.workbookBase64)throw Error('Load the original workbook first to retain a complete .xlsx snapshot.');const saved=await api('snapshots',{plan:data});await loadHistory();historyState.viewedId=saved.saved.id;data.mode='saved';updateSource();render();$('message').textContent='Saved the complete workbook and all '+data.rows.length+' parsed plan rows. History is retained across reloads.';}
document.addEventListener('click',async e=>{const view=e.target.closest('[data-view]'),week=e.target.closest('[data-week]'),risk=e.target.closest('[data-risk]'),dep=e.target.closest('[data-dependency]'),load=e.target.closest('[data-load-snapshot]'),download=e.target.closest('[data-download-snapshot]');if(view){state.view=view.dataset.view;render();}if(week){e.preventDefault();historyState.week=week.dataset.week;state.view='dates';render();}if(risk){historyState.risk=risk.dataset.risk;render();}if(dep)showDependency(dep.dataset.dependency);try{
 if(load){data=await api('snapshots/'+encodeURIComponent(load.dataset.loadSnapshot));data.mode='saved';historyState.viewedId=load.dataset.loadSnapshot;controls();updateSource();render();$('message').textContent='Viewing saved observation. This does not overwrite newer history.';}
 if(download){const plan=await api('snapshots/'+encodeURIComponent(download.dataset.downloadSnapshot));if(plan.workbookBase64){const bytes=Uint8Array.from(atob(plan.workbookBase64),c=>c.charCodeAt(0));downloadBlob(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),plan.name);}else downloadBlob(new Blob([JSON.stringify(plan,null,2)],{type:'application/json'}),'parsed-baseline.json');}
 if(e.target.closest('#save-snapshot'))await saveCurrent();
 if(e.target.closest('#retry-history')){await loadHistory();render();}
 if(e.target.closest('#compare-snapshots')){const [a,b]=await Promise.all([api('snapshots/'+encodeURIComponent($('compare-from').value)),api('snapshots/'+encodeURIComponent($('compare-to').value))]);historyState.compare=HistoryCore.diff(a,b);$('snapshot-diff').innerHTML=historyState.compare.length?renderDiff():'<p>No differences in tracked fields.</p>';}
 if(e.target.closest('#print-report'))window.print();
 if(e.target.closest('#download-report')){if(!reportStyles)throw Error('Report styles are still loading. Please try again.');downloadBlob(new Blob(['<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Eagle B0 delivery review</title><style>'+reportStyles+'body{padding:24px;background:white}.management-report{max-width:1100px;margin:auto}</style></head><body>'+reportMarkup(selected())+'</body></html>'],{type:'text/html'}),'Eagle-B0-review-'+state.asOf+'.html');}
 }catch(err){$('message').textContent=err.message;}
});
document.addEventListener('change',e=>{const map={'history-basis':'basis','history-series':'series','change-week':'week','change-field':'changeField','change-kind':'kind'};if(map[e.target.id]){historyState[map[e.target.id]]=e.target.value;render();}});
document.addEventListener('submit',async e=>{if(e.target.id!=='dependency-review-form')return;e.preventDefault();const f=e.target,values=new FormData(f);const decision=values.get('decision'),note=values.get('note').trim();if(decision!=='unreviewed'&&!note){$('review-result').textContent='Please record the reviewer and decision evidence.';return;}try{const result=await api('dependency-review',{id:f.dataset.id,decision,note});historyState.reviews=historyState.reviews.filter(r=>r.id!==result.id).concat(result);$('review-result').textContent='Review saved. No Jira link was created.';render();}catch(e){$('review-result').textContent=e.message;}});
